// Paste the same value as SHOP_TOKEN in Vercel.
const TOKEN = 'PASTE_SHOP_TOKEN_HERE';

const item = $input.first().json;
const headers = item.headers || {};
const auth = headers['authorization'] || headers['Authorization'] || '';
if (auth !== `Bearer ${TOKEN}`) {
  throw new Error('Wrong or missing authorization token');
}
const b = item.body;
const lines = (b.lines || []).map((l) => `• ${l.name} — ${l.qty} ${l.unit}`).join('\n');
const subject = `New order from ${b.shopName || 'Munim Kirana'}`;
const text = `Hello ${b.distributorName || 'Distributor'},\n\nPlease send the following to ${b.shopName || 'our shop'}:\n\n${lines}\n\nApproved by the owner in Munim.\nThank you!`;
return [{ json: { subject, text } }];
